/*! msgpack 极简解码器（仅 decode，替代原 msgpack-lite 浏览器包 51KB → ~5KB）。
 *  数据由构建端 msgpack-lite 编码，实测仅用到 map/int/array/str；本实现完整覆盖
 *  nil/bool/int/float/str/bin/array/map 规范子集，ext 类型直接抛错（数据不产生）。
 *  用法与旧包一致：全局 msgpack.decode(buf) → 对象/数组。Worker 与主线程通用。
 *  保持文件名 msgpack.min.js 不变：search-worker importScripts 与 today.js 动态注入均无感。 */
(function () {
  'use strict';
  function decoder(u8) {
    var pos = 0;
    var view = new DataView(u8.buffer, u8.byteOffset, u8.byteLength);
    var td = new TextDecoder();
    function bytes(n) { var r = u8.subarray(pos, pos + n); pos += n; return r; }
    function u8v() { return u8[pos++]; }
    function u16() { var v = view.getUint16(pos); pos += 2; return v; }
    function u32() { var v = view.getUint32(pos); pos += 4; return v; }
    function i8() { var v = view.getInt8(pos); pos += 1; return v; }
    function i16() { var v = view.getInt16(pos); pos += 2; return v; }
    function i32() { var v = view.getInt32(pos); pos += 4; return v; }
    function f32() { var v = view.getFloat32(pos); pos += 4; return v; }
    function f64() { var v = view.getFloat64(pos); pos += 8; return v; }
    function u64() {
      var hi = view.getUint32(pos), lo = view.getUint32(pos + 4); pos += 8;
      var n = hi * 4294967296 + lo;
      return n <= 9007199254740991 ? n : BigInt(hi) * 4294967296n + BigInt(lo);
    }
    function str(n) { return td.decode(bytes(n)); }
    function arr(n) { var a = new Array(n); for (var k = 0; k < n; k++) a[k] = read(); return a; }
    function map(n) {
      var o = {};
      for (var k = 0; k < n; k++) { var key = read(); o[key] = read(); }
      return o;
    }
    function read() {
      var t = u8v();
      if (t < 0x80) return t;                 // positive fixint
      if (t >= 0xe0) return t - 0x100;        // negative fixint
      if (t < 0x90) return map(t & 0x0f);     // fixmap
      if (t < 0xa0) return arr(t & 0x0f);     // fixarray
      if (t < 0xc0) return str(t & 0x1f);     // fixstr
      switch (t) {
        case 0xc0: return null;
        case 0xc2: return false;
        case 0xc3: return true;
        case 0xc4: return bytes(u8v());
        case 0xc5: return bytes(u16());
        case 0xc6: return bytes(u32());
        case 0xca: return f32();
        case 0xcb: return f64();
        case 0xcc: return u8v();
        case 0xcd: return u16();
        case 0xce: return u32();
        case 0xcf: return u64();
        case 0xd0: return i8();
        case 0xd1: return i16();
        case 0xd2: return i32();
        case 0xd3: { var v = u64(); return typeof v === 'bigint' && v >= 9223372036854775808n ? v - 18446744073709551616n : v; }
        case 0xd9: return str(u8v());
        case 0xda: return str(u16());
        case 0xdb: return str(u32());
        case 0xdc: return arr(u16());
        case 0xdd: return arr(u32());
        case 0xde: return map(u16());
        case 0xdf: return map(u32());
        default: throw new Error('msgpack: unsupported type 0x' + t.toString(16));
      }
    }
    return read();
  }
  var api = {
    decode: function (buf) { return decoder(buf instanceof Uint8Array ? buf : new Uint8Array(buf)); }
  };
  if (typeof globalThis !== 'undefined') globalThis.msgpack = api;
  else if (typeof self !== 'undefined') self.msgpack = api;
  else if (typeof window !== 'undefined') window.msgpack = api;
})();
